import { Injectable } from '@nestjs/common';
import { WorkflowResponseDto } from '../../../../../workflows-v2/dtos/workflow-response.dto';
import { StepResponseDto } from '../../../../../workflows-v2/dtos/step.response.dto';
import { IWorkflowNormalizer, INormalizedWorkflow, INormalizedStep } from '../types/workflow-sync.types';

@Injectable()
export class WorkflowNormalizer implements IWorkflowNormalizer {
  /**
   * We want to normalize the workflow and omit any fields that are autogenerated by the system
   * Or are not relevant for the comparison
   */
  normalizeWorkflow(workflow: WorkflowResponseDto): INormalizedWorkflow {
    const {
      workflowId,
      name,
      active = false,
      tags = [],
      description,
      payloadSchema,
      validatePayload,
      steps = [],
      preferences,
    } = workflow;

    return {
      workflowId,
      name,
      active,
      tags,
      description,
      payloadSchema,
      validatePayload,
      steps: steps.map((step) => this.normalizeStep(step)),
      preferences,
    };
  }

  normalizeStep(step: StepResponseDto): INormalizedStep {
    const { stepId, name, type, controlValues } = step;

    return {
      stepId,
      name,
      type,
      controlValues,
    };
  }
}
